// Booking panel for the business demo pages, /demo/b/<slug>/ (Ro, 21 Oct 2026).
// The page is generated by tools/build-business-demos.mjs from
// data/business-layer/<slug>.json and carries its settings in #demo-config.
// Prices, dates, places, questions and the cancellation policy come from the
// test booking service; the Worker works out the real total, never this page.
// Stripe test mode only. Demo traffic is tracked (never as demand); team
// visits with ?team=1 are not tracked for the rest of the browser session.
(function () {
  var cfgEl = document.getElementById('demo-config');
  if (!cfgEl) return;
  var C = JSON.parse(cfgEl.textContent);
  // Local Worker when previewing on localhost, the test booking service otherwise.
  var API = /^(localhost|127\.0\.0\.1)$/.test(location.hostname) ? 'http://127.0.0.1:8787' : 'https://api-test.thresholdbooking.com';
  var SLUG = C.slug, TZ = C.timezone, BIZ = C.business;
  // booking_mode (data file): sandbox takes test bookings; off shows the page only.
  // Pages built before booking_mode carry none and keep working as they did.
  var OFF = C.booking_mode === 'off';
  var $ = function (id) { return document.getElementById(id); };
  var q = new URLSearchParams(location.search);
  var KEYS = C.options.map(function (o) { return o.experience; });
  var state = {
    key: KEYS.indexOf(q.get('x')) >= 0 ? q.get('x') : KEYS[0],
    meta: null, slots: [], date: null, slot: null, people: 1, shown: 8,
    answers: {}, addons: {}, camOn: false, pairPart: '', idemKey: null, idemFor: '', loadSeq: 0
  };
  var ERR_ICON = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><line x1="12" y1="7" x2="12" y2="13"/><line x1="12" y1="17" x2="12" y2="17"/></svg>';

  // ── Demo traffic (POST /demo/track). Never personal data. ──
  function rid() { return (window.crypto && crypto.randomUUID ? crypto.randomUUID() : String(Math.random()).slice(2) + Date.now()).replace(/[^A-Za-z0-9-]/g, ''); }
  var TEAM = q.get('team') === '1';
  try { if (TEAM) sessionStorage.setItem('th_team', '1'); TEAM = TEAM || sessionStorage.getItem('th_team') === '1'; } catch (e) {}
  var VISITOR = null;
  try { VISITOR = localStorage.getItem('th_demo_visitor'); } catch (e) {}
  if (!VISITOR || !/^[A-Za-z0-9-]{8,64}$/.test(VISITOR)) { VISITOR = rid(); try { localStorage.setItem('th_demo_visitor', VISITOR); } catch (e) {} }
  var SOURCE = (function () {
    var u = q.get('utm_source');
    if (u && /^[a-z0-9._-]{1,100}$/i.test(u)) return u.toLowerCase();
    try { if (document.referrer) { var h = new URL(document.referrer).hostname; if (h && h !== location.hostname) return h; } } catch (e) {}
    return 'direct';
  })();
  function track(event) {
    if (TEAM) return;
    try {
      // text/plain keeps it a simple request, so it still goes out as the page leaves for Stripe.
      fetch(API + '/demo/track', { method: 'POST', headers: { 'content-type': 'text/plain;charset=UTF-8' }, keepalive: true,
        body: JSON.stringify({ business: SLUG, event: event, visitor: VISITOR, source: SOURCE, experience: state.key }) }).catch(function () {});
    } catch (e) {}
  }

  // ── Formatting (business time, Australian style) ──
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  function money(c) { return '$' + (c / 100).toLocaleString('en-AU', { minimumFractionDigits: c % 100 ? 2 : 0, maximumFractionDigits: 2 }); }
  function utcDay(d) { return Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10)); }
  function isoWeekday(d) { return new Date(utcDay(d)).getUTCDay() || 7; }
  function parts(d) { return { wd: DAYS[new Date(utcDay(d)).getUTCDay()], d: +d.slice(8, 10), mon: MONTHS[+d.slice(5, 7) - 1] }; }
  function days(a, b) { return Math.round((utcDay(b) - utcDay(a)) / 864e5) + 1; }
  function range(a, b) {
    var p = parts(a);
    if (a === b) return p.wd + ' ' + p.d + ' ' + p.mon;
    var r = parts(b);
    return p.mon === r.mon ? p.wd + ' ' + p.d + ' to ' + r.wd + ' ' + r.d + ' ' + r.mon : p.wd + ' ' + p.d + ' ' + p.mon + ' to ' + r.wd + ' ' + r.d + ' ' + r.mon;
  }
  function clock(t) { var h = +t.slice(0, 2), m = t.slice(3, 5); return (h % 12 || 12) + (m === '00' ? '' : ':' + m) + (h < 12 ? 'am' : 'pm'); }
  function api(method, path, body) {
    return fetch(API + path, { method: method, headers: { 'content-type': 'application/json' }, body: body ? JSON.stringify(body) : undefined })
      .then(function (r) { return r.json().catch(function () { return {}; }).then(function (j) { return { status: r.status, body: j }; }); });
  }
  function text(el, s) { el.textContent = s; return el; }
  // Visible placeholders: [TO CONFIRM ...] and [PERMISSION NEEDED] are marked, as on the page.
  function rich(el, s) {
    el.textContent = '';
    String(s || '').split(/(\[(?:TO CONFIRM|PERMISSION NEEDED)[^\]]*\])/).forEach(function (bit) {
      if (!bit) return;
      if (/^\[(TO CONFIRM|PERMISSION NEEDED)/.test(bit)) { var sp = document.createElement('span'); sp.className = 'tbc'; sp.textContent = bit; el.appendChild(sp); }
      else el.appendChild(document.createTextNode(bit));
    });
    return el;
  }
  function list(el, items, html) {
    el.innerHTML = items.map(function () { return html; }).join('');
    return [].slice.call(el.children);
  }
  function showError(el, msg) { el.textContent = msg; el.hidden = !msg; }
  function X() { return C.experiences[state.key]; }
  function party(n) { return n + ' ' + (n > 1 ? C.party.many : C.party.one); }
  function screening() { return (state.meta && state.meta.screening) || []; }

  // ── The experience choice (first thing in the panel) ──
  function renderChoices() {
    list($('choices'), C.options, '<button type="button" class="opt" aria-pressed="false"><span></span><small></small></button>')
      .forEach(function (b, i) {
        var o = C.options[i];
        b.dataset.key = o.experience;
        text(b.children[0], o.label);
        rich(b.children[1], o.sub || '');
        b.setAttribute('aria-pressed', o.experience === state.key);
        b.onclick = function () { if (o.experience !== state.key) choose(o.experience); };
      });
  }

  function choose(key) {
    state.key = key; state.meta = null; state.slot = null; state.date = null; state.shown = 8;
    state.answers = {}; state.addons = {}; state.camOn = false;
    [].forEach.call($('choices').children, function (b) { b.setAttribute('aria-pressed', b.dataset.key === key); });
    staticContent();
    loadDates();
  }

  function staticContent() {
    var x = X();
    list($('facts'), x.facts, '<li></li>').forEach(function (li, i) { rich(li, x.facts[i]); });
    list($('included'), x.included || [], '<li style="display:flex;gap:8px;"><span aria-hidden="true">&check;</span><span></span></li>')
      .forEach(function (li, i) { rich(li.lastChild, x.included[i]); });
    list($('notes'), x.notes || [], '<li></li>').forEach(function (li, i) { rich(li, x.notes[i]); });
    $('notes').hidden = !(x.notes || []).length;
    $('lead').hidden = $('panelLead').hidden = !x.lead;
    text($('lead'), x.lead || ''); text($('panelLead'), x.lead || '');
    rich($('datesNote'), x.dates_note || '');
    if ($('knowList')) knowList($('knowList'), x.good_to_know);
  }
  // Good to know (design system 6.21): the same list on the page and after booking.
  function knowList(el, items) {
    items = items || [];
    list(el, items, '<li></li>').forEach(function (li, i) { rich(li, items[i]); });
    el.hidden = !items.length;
    return items.length;
  }

  // ── Step 1 groups: chip questions (saved to the booking) and price add-ons ──
  function renderGroups() {
    var x = X(), html = [], blocks = [];
    screening().forEach(function (sq) {
      if (sq.ui !== 'chips') return;
      blocks.push({ kind: 'q', q: sq });
    });
    if (x.pricing === 'addons') (C.addons || []).forEach(function (g) { if (!(g.hide_when_pair && state.pairPart)) blocks.push({ kind: 'addon', g: g }); });
    $('groups').innerHTML = blocks.map(function (b, i) {
      return '<div class="bp-block" id="grp' + i + '"><p class="bp-label" id="grp' + i + '-label"></p><div class="opt-list" role="group" aria-labelledby="grp' + i + '-label"></div><p class="bp-field-error" id="grp' + i + '-err" hidden></p></div>';
    }).join('');
    blocks.forEach(function (b, i) {
      var box = $('grp' + i), wrap = box.querySelector('.opt-list');
      if (b.kind === 'q') {
        text($('grp' + i + '-label'), b.q.label);
        box.dataset.q = b.q.key;
        list(wrap, b.q.options, '<button type="button" class="opt opt--chip" aria-pressed="false"><span></span></button>').forEach(function (btn, j) {
          var v = b.q.options[j];
          text(btn.firstChild, v);
          btn.setAttribute('aria-pressed', state.answers[b.q.key] === v);
          btn.onclick = function () {
            state.answers[b.q.key] = v;
            [].forEach.call(wrap.children, function (c) { c.setAttribute('aria-pressed', c === btn); });
            groupError(i, '');
            if (x.filter && x.filter.question === b.q.key) { state.shown = 8; renderDates(); }
          };
        });
      } else if (b.g.toggle) {
        text($('grp' + i + '-label'), b.g.label);
        var t = list(wrap, [1], '<button type="button" class="opt opt--chip" aria-pressed="false"><span></span><small></small></button>')[0];
        text(t.firstChild, b.g.option); rich(t.lastChild, b.g.sub || '');
        t.setAttribute('aria-pressed', state.camOn);
        t.onclick = function () { state.camOn = !state.camOn; t.setAttribute('aria-pressed', state.camOn); render(); };
      } else {
        text($('grp' + i + '-label'), b.g.label);
        if (!state.addons[b.g.list]) state.addons[b.g.list] = b.g.options[0][0];
        list(wrap, b.g.options, '<button type="button" class="opt opt--chip" aria-pressed="false"><span></span><small></small></button>').forEach(function (btn, j) {
          var o = b.g.options[j];
          text(btn.firstChild, o[1]); text(btn.lastChild, o[2] || '');
          btn.setAttribute('aria-pressed', state.addons[b.g.list] === o[0]);
          btn.onclick = function () {
            state.addons[b.g.list] = o[0];
            [].forEach.call(wrap.children, function (c) { c.setAttribute('aria-pressed', c === btn); });
            render();
          };
        });
      }
    });
  }
  function groupError(i, msg) {
    var e = $('grp' + i + '-err'); if (!e) return;
    e.hidden = !msg; e.innerHTML = msg ? ERR_ICON + '<span></span>' : '';
    if (msg) e.lastChild.textContent = msg;
  }

  // ── Party: a stepper, or "Just me / Flights for Two" ──
  function maxPeople() {
    var m = state.meta; if (!m) return 1;
    var cap = Math.min(m.capacity_per_session || 1, m.people_max || 99);
    return state.slot ? Math.min(cap, state.slot.places_left) : cap;
  }
  function renderParty() {
    if (C.party.mode === 'pair') {
      $('party').innerHTML = '<div class="bp-block"><p class="bp-label" id="partyLabel"></p><div class="opt-list" role="group" aria-labelledby="partyLabel"></div></div>';
      text($('partyLabel'), C.party.label);
      list($('party').querySelector('.opt-list'), C.party.choices, '<button type="button" class="opt opt--chip" aria-pressed="false"><span></span><small></small></button>').forEach(function (b, i) {
        var c = C.party.choices[i];
        text(b.firstChild, c.label); text(b.lastChild, c.sub || '');
        b.dataset.n = c.n;
        b.onclick = function () { state.people = c.n; state.pairPart = c.part || ''; renderGroups(); render(); };
      });
    } else {
      $('party').innerHTML = '<div class="bp-row"><p class="bp-label"></p><div class="stepper" role="group"><button type="button" id="minus" disabled>&minus;</button><output id="people" aria-live="polite">1</output><button type="button" id="plus">+</button></div></div>';
      text($('party').querySelector('.bp-label'), C.party.label);
      $('party').querySelector('.stepper').setAttribute('aria-label', 'Number of ' + C.party.many);
      $('minus').setAttribute('aria-label', 'One fewer ' + C.party.one);
      $('plus').setAttribute('aria-label', 'One more ' + C.party.one);
      $('minus').onclick = function () { state.people--; render(); };
      $('plus').onclick = function () { state.people++; render(); };
    }
  }
  function syncParty() {
    var max = maxPeople();
    state.people = Math.max(1, Math.min(state.people, max));
    if (C.party.mode === 'pair') {
      if (state.people < 2) state.pairPart = '';
      [].forEach.call($('party').querySelectorAll('.opt'), function (b) {
        b.disabled = +b.dataset.n > max;
        b.setAttribute('aria-pressed', +b.dataset.n === state.people);
      });
    } else {
      $('people').textContent = state.people;
      $('minus').disabled = state.people <= 1;
      $('plus').disabled = state.people >= max;
    }
  }

  // ── Price, as the Worker will work it out ──
  function priceOf(key) {
    var p = (state.meta.prices || []).filter(function (x) { return x.key === key; })[0];
    return p || null;
  }
  function quote() {
    var m = state.meta, x = X(), n = state.people;
    if (x.pricing === 'first_extra') {
      var f = priceOf('first'), e = priceOf('extra');
      return { units: { first: 1, extra: n - 1 }, total: f.price_cents + e.price_cents * (n - 1),
        lines: [[f.label, money(f.price_cents)]].concat(n > 1 ? [[e.label + ' × ' + (n - 1), money(e.price_cents * (n - 1))]] : []) };
    }
    if (x.pricing === 'addons') {
      var bits = [];
      (C.addons || []).forEach(function (g) {
        if (g.toggle) bits[g.list] = state.pairPart || (state.camOn ? g.toggle : '');
        else bits[g.list] = state.addons[g.list] || g.options[0][0];
      });
      var key = bits.filter(Boolean).join('-'), p = priceOf(key);
      if (!p) return null;
      var u = {}; u[key] = n;
      return { units: u, total: p.price_cents * n, lines: [[p.label + (n > 1 ? ' × ' + n : ''), money(p.price_cents * n)]] };
    }
    return { units: null, total: m.price_cents * n,
      lines: [[money(m.price_cents) + ' × ' + party(n), money(m.price_cents * n)]] };
  }

  function render() {
    if (!state.meta) return;
    syncParty();
    var qt = state.slot ? quote() : null;
    $('total').hidden = !qt;
    if (qt) $('totalValue').textContent = money(qt.total);
    $('bookingCta').disabled = !qt || OFF;
    if (!qt) return;
    var s = state.slot;
    $('chosen').textContent = (labelFor(state.key) + ' · ' + range(s.date_local, s.end_date_local) + ', ' + clock(s.time_local) + ' · ' + party(state.people));
    $('summary').innerHTML = qt.lines.map(function () { return '<div class="row"><span></span><span></span></div>'; }).join('') + '<div class="row"><b></b><b></b></div>';
    var rows = $('summary').children;
    qt.lines.forEach(function (l, i) { text(rows[i].children[0], l[0]); text(rows[i].children[1], l[1]); });
    text(rows[qt.lines.length].children[0], 'Total (held, not charged)');
    text(rows[qt.lines.length].children[1], money(qt.total));
  }
  function labelFor(key) { var o = C.options.filter(function (x) { return x.experience === key; })[0]; return (state.meta && state.meta.experience_name) || (o ? o.label : key); }

  // ── Dates and times ──
  function visibleSlots() {
    var x = X(), f = x.filter;
    if (!f) return state.slots;
    var v = state.answers[f.question];
    var hide = (v && f.hide_weekdays[v]) || [];
    return state.slots.filter(function (s) { return hide.indexOf(isoWeekday(s.date_local)) < 0; });
  }
  function renderDates() {
    var x = X(), f = x.filter, slots = visibleSlots();
    $('timesBlock').hidden = true;
    var hint = f && state.answers[f.question] && f.hint && f.hint[state.answers[f.question]];
    $('filterHint').hidden = !hint; text($('filterHint'), hint || '');
    if (f && !state.answers[f.question]) {
      $('dates').innerHTML = '<p class="bp-note"></p>';
      text($('dates').firstChild, 'Choose ' + (screening().filter(function (s) { return s.key === f.question; })[0] || { label: 'an option' }).label.toLowerCase() + ' first.');
      $('moreDates').hidden = true; return;
    }
    if (state.slot && slots.indexOf(state.slot) < 0) { state.slot = null; state.date = null; render(); }
    var byDate = [], seen = {};
    slots.forEach(function (s) { if (!seen[s.date_local]) { seen[s.date_local] = []; byDate.push(s.date_local); } seen[s.date_local].push(s); });
    if (!byDate.length) { $('dates').innerHTML = '<p class="bp-note">No dates open right now.</p>'; $('moreDates').hidden = true; return; }
    var show = byDate.slice(0, state.shown);
    $('dates').innerHTML = show.map(function (d, i) {
      var ss = seen[d], open = ss.filter(function (s) { return s.places_left > 0; }), s0 = ss[0], p = parts(d);
      var n = days(s0.date_local, s0.end_date_local);
      var note = !open.length ? 'Full' : ss.length > 1 ? ss.length + ' times' : clock(s0.time_local) + (s0.places_left <= 3 ? ', ' + s0.places_left + ' left' : '');
      var label = n > 1 ? range(s0.date_local, s0.end_date_local) : p.wd + ' ' + p.d + ' ' + p.mon;
      return '<button type="button" class="date-opt" data-d="' + d + '" aria-pressed="' + (state.date === d) + '" aria-label="' + label + ', ' + note + '"' + (open.length ? '' : ' disabled') + '>'
        + '<span>' + label + '</span>' + (n > 1 ? '<small>' + n + ' days</small>' : '') + '<small>' + note + '</small></button>';
    }).join('');
    $('moreDates').hidden = byDate.length <= state.shown;
    state.byDate = seen;
    if (state.date && seen[state.date] && seen[state.date].length > 1) renderTimes();
  }
  function renderTimes() {
    var ss = state.byDate[state.date];
    $('timesBlock').hidden = false;
    $('times').innerHTML = ss.map(function (s, i) {
      var note = s.places_left === 0 ? 'Full' : s.places_left <= 3 ? s.places_left + ' left' : '';
      return '<button type="button" class="date-opt" data-i="' + i + '" aria-pressed="' + (state.slot === s) + '"' + (s.places_left ? '' : ' disabled') + '><span>' + clock(s.time_local) + '</span>' + (note ? '<small>' + note + '</small>' : '') + '</button>';
    }).join('');
  }
  function pickSlot(s) {
    state.slot = s;
    var dur = s.date_local !== s.end_date_local && (state.meta.sessions_per_booking || 1) > 1
      ? clock(s.time_local) + ' each day, ' + days(s.date_local, s.end_date_local) + ' days'
      : clock(s.time_local) + ' to ' + clock(s.end_time_local);
    $('timesNote').textContent = range(s.date_local, s.end_date_local) + ', ' + dur + '.';
    showError($('err'), '');
    render();
  }
  $('dates').addEventListener('click', function (e) {
    var b = e.target.closest('[data-d]'); if (!b || b.disabled) return;
    state.date = b.dataset.d; state.slot = null;
    [].forEach.call($('dates').children, function (x) { x.setAttribute('aria-pressed', x === b); });
    var ss = state.byDate[state.date].filter(function (s) { return s.places_left > 0; });
    if (state.byDate[state.date].length === 1) { $('timesBlock').hidden = true; pickSlot(ss[0]); }
    else { $('timesNote').textContent = ''; renderTimes(); render(); }
  });
  $('times').addEventListener('click', function (e) {
    var b = e.target.closest('[data-i]'); if (!b || b.disabled) return;
    [].forEach.call($('times').children, function (x) { x.setAttribute('aria-pressed', x === b); });
    pickSlot(state.byDate[state.date][+b.dataset.i]);
  });
  $('moreDates').onclick = function () { state.shown += 8; renderDates(); };

  // ── Policy and how-it-works, from the business's own settings ──
  function cancelLine(policy) {
    if (!policy || policy === 'ask the business') return 'Ask the business about cancellation before you book.';
    if (policy.text) return policy.text;
    var tiers = policy.tiers.slice().sort(function (a, b) { return b.hours_before - a.hours_before; });
    var lines = tiers.map(function (t, i) {
      var what = t.refund_pct === 100 ? 'a full refund' : 'a ' + t.refund_pct + '% refund';
      return i === 0 ? 'Cancel ' + t.hours_before + ' hours or more before the start for ' + what + '.' : 'Cancel ' + t.hours_before + ' to ' + tiers[i - 1].hours_before + ' hours before for ' + what + '.';
    });
    if (tiers.length) lines.push('Less than ' + tiers[tiers.length - 1].hours_before + ' hours before, no refund unless the business cancels or reschedules.');
    return lines.join(' ');
  }
  function howSteps(m) {
    var steps = [
      ['Choose, then add your details', 'Then add your card on a secure Stripe page. It\'s held, not charged.'],
      [BIZ + ' confirms within ' + m.response_hours + ' hours', 'Once they confirm, the payment is taken. If they can\'t, the hold is released and you\'re not charged.'],
      ['Turn up on the day', 'Everything you need to know is in your confirmation email.']
    ];
    list($('howSteps'), steps, '<li><span class="n"></span><span><b></b><span class="prose" style="display:block;"></span></span></li>').forEach(function (li, i) {
      text(li.querySelector('.n'), i + 1); text(li.querySelector('b'), steps[i][0]); text(li.querySelector('.prose'), steps[i][1]);
    });
  }

  function loadDates() {
    var seq = ++state.loadSeq, key = state.key;
    $('dates').innerHTML = '<p class="bp-note">Loading dates...</p>';
    $('moreDates').hidden = true; $('timesBlock').hidden = true; $('timesNote').textContent = '';
    $('total').hidden = true; $('bookingCta').disabled = true;
    var from = new Date().toISOString().slice(0, 10), to = new Date(Date.now() + 180 * 864e5).toISOString().slice(0, 10);
    api('GET', '/availability?business=' + SLUG + '&experience=' + key + '&from=' + from + '&to=' + to).then(function (r) {
      if (seq !== state.loadSeq) return;
      if (r.status !== 200) { $('dates').innerHTML = ''; showError($('err'), r.body.message || 'Dates could not be loaded.'); return; }
      var m = state.meta = r.body; state.slots = m.slots;
      $('stickyPrice').textContent = $('stickyPrice').dataset.fixed || ('From ' + money(m.price_cents));
      rich($('policy'), cancelLine(m.cancellation_policy));
      $('policyHold').textContent = 'Your card is held, not charged, until ' + BIZ + ' confirms, within ' + m.response_hours + ' hours. If they can\'t confirm, the hold is released.';
      rich($('policyCancel'), cancelLine(m.cancellation_policy));
      howSteps(m);
      renderGroups();
      renderParty();
      if (!m.bookable) { $('dates').innerHTML = '<p class="bp-note">Details coming. Ask ' + BIZ + ' about this one.</p>'; return; }
      if (OFF) showError($('err'), 'Online booking isn\'t open yet.' + (C.phone ? ' Call ' + BIZ + ' on ' + C.phone + ' to book.' : ''));
      renderDates();
      render();
    }).catch(function () { if (seq === state.loadSeq) { $('dates').innerHTML = ''; showError($('err'), 'The booking service is not reachable right now.'); } });
  }

  // ── Step 2: details, riders, questions ──
  var R = C.riders;
  function riderQ() { return R && screening().filter(function (s) { return s.key === R.question; })[0]; }
  function renderStep2() {
    if (C.pickup) { $('pickup').hidden = false; rich($('pickup'), C.pickup); }
    // One row per rider or passenger.
    if (riderQ()) {
      var rows = [];
      for (var i = 0; i < state.people; i++) rows.push(i);
      $('riders').innerHTML = '<div class="bp-riders"><p class="bp-label" id="ridersLabel"></p><p class="bp-hint" id="ridersHint" style="margin:0 0 var(--s-3);"></p>'
        + rows.map(function (i) {
          return (state.people > 1 ? '<p class="bp-q" aria-hidden="true">' + R.row + ' ' + (i + 1) + '</p>' : '')
            + '<div class="bp-rider" role="group" aria-label="' + R.row + ' ' + (i + 1) + '">' + R.fields.map(function (f) {
            var id = 'r' + i + '-' + f.key;
            return '<div class="bp-field" id="f-' + id + '"><label for="' + id + '">' + f.label + '</label>'
              + '<input id="' + id + '" inputmode="numeric" autocomplete="off" aria-describedby="' + id + '-err" /><p class="bp-field-error" id="' + id + '-err" hidden></p></div>';
          }).join('') + '</div>';
        }).join('') + '</div>';
      text($('ridersLabel'), R.title); text($('ridersHint'), R.hint || '');
    } else $('riders').innerHTML = '';
    // Yes/No questions, required checkboxes, and the guardian consent.
    var qs = screening().filter(function (s) { return s.ui !== 'chips' && s.ui !== 'composed'; });
    state.questions = qs;
    $('questions').innerHTML = qs.map(function (x, i) {
      if (x.ui === 'checkbox') {
        return '<div class="bp-field" id="f-q' + i + '"><label class="bp-check"><input type="checkbox" id="q' + i + '" aria-describedby="q' + i + '-err" /><span id="q' + i + '-label"></span></label><p class="bp-field-error" id="q' + i + '-err" hidden></p></div>';
      }
      return '<div class="bp-field" id="f-q' + i + '"><span class="bp-q" id="q' + i + '-label"></span>'
        + '<div class="bp-choice" role="radiogroup" aria-labelledby="q' + i + '-label" aria-describedby="q' + i + '-err">'
        + '<label><input type="radio" name="q' + i + '" value="yes" id="q' + i + '" /><span>Yes</span></label>'
        + '<label><input type="radio" name="q' + i + '" value="no" /><span>No</span></label></div>'
        + '<p class="bp-field-error" id="q' + i + '-err" hidden></p></div>';
    }).join('') + (R && R.consent ? '<div class="bp-field" id="f-consent" hidden><label class="bp-check"><input type="checkbox" id="consent" aria-describedby="consent-err" /><span id="consent-label"></span></label><p class="bp-field-error" id="consent-err" hidden></p></div>' : '');
    qs.forEach(function (x, i) {
      text($('q' + i + '-label'), x.label);
      document.querySelectorAll('#f-q' + i + ' input').forEach(function (r) {
        r.addEventListener('change', function () { setFieldError('q' + i, ''); syncConsent(); });
      });
    });
    if ($('consent-label')) { text($('consent-label'), R.consent.label); $('consent').onchange = function () { setFieldError('consent', ''); }; }
    syncConsent();
  }
  function answer(i) {
    var x = state.questions[i];
    if (x.ui === 'checkbox') return $('q' + i).checked;
    var c = document.querySelector('input[name="q' + i + '"]:checked'); return c ? c.value === 'yes' : null;
  }
  function needsConsent() {
    if (!R || !R.consent) return false;
    var i = (state.questions || []).map(function (x) { return x.key; }).indexOf(R.consent.if);
    return i >= 0 && answer(i) === true;
  }
  function syncConsent() { if ($('f-consent')) $('f-consent').hidden = !needsConsent(); }

  var FIELDS = [
    ['name', function (v) { return v ? '' : 'Add your name'; }],
    ['email', function (v) { return !v ? 'Add an email we can send your booking to' : /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v) ? '' : 'That email doesn\'t look right'; }],
    ['phone', function (v) { return v.replace(/[^\d]/g, '').length >= 6 ? '' : 'Add a phone number'; }]
  ];
  function setFieldError(id, msg) {
    var box = $('f-' + id), err = $(id + '-err');
    if (!box || !err) return;
    box.classList.toggle('has-error', !!msg);
    var input = $(id);
    if (input && input.tagName === 'INPUT' && input.type !== 'radio' && input.type !== 'checkbox') input.setAttribute('aria-invalid', msg ? 'true' : 'false');
    err.hidden = !msg;
    err.innerHTML = msg ? ERR_ICON + '<span></span>' : '';
    if (msg) err.lastChild.textContent = msg;
  }
  function riderCheck(f, v) {
    if (!v) return f.required ? 'Add a ' + f.label.replace(/\s*\(.*\)/, '').toLowerCase() : '';
    var n = Number(v.replace(',', '.'));
    if (!isFinite(n) || n <= 0) return 'Use a number in ' + f.unit;
    if (f.max && n > f.max) return f.over || 'That looks too high. Use a number in ' + f.unit;
    if (f.min && n < f.min) return 'That looks too low. Use a number in ' + f.unit;
    return '';
  }
  function checkFields() {
    var first = null;
    function flag(id, msg) { setFieldError(id, msg); if (msg && !first) first = id; }
    FIELDS.forEach(function (f) { flag(f[0], f[1]($(f[0]).value.trim())); });
    if (riderQ()) for (var i = 0; i < state.people; i++) R.fields.forEach(function (f) { var id = 'r' + i + '-' + f.key; flag(id, riderCheck(f, $(id).value.trim())); });
    (state.questions || []).forEach(function (x, i) {
      var a = answer(i);
      flag('q' + i, x.ui === 'checkbox' ? (a ? '' : 'Tick this to book a ' + (X().lead || 'this session').toLowerCase().replace(/s$/, '')) : a === null ? 'Choose yes or no' : '');
    });
    if (needsConsent()) flag('consent', $('consent').checked ? '' : 'A parent or guardian needs to consent for anyone under 18');
    return first;
  }
  FIELDS.forEach(function (f) {
    $(f[0]).addEventListener('input', function () { if ($('f-' + f[0]).classList.contains('has-error') && !f[1]($(f[0]).value.trim())) setFieldError(f[0], ''); });
  });
  function composed() {
    var out = {};
    if (riderQ()) {
      var rows = [];
      for (var i = 0; i < state.people; i++) {
        var bits = R.fields.map(function (f) { var v = $('r' + i + '-' + f.key).value.trim(); return v ? v + ' ' + f.unit : ''; }).filter(Boolean);
        rows.push(R.row + ' ' + (i + 1) + ': ' + (bits.join(', ') || 'not given'));
      }
      if (needsConsent()) rows.push('Parent or guardian consent: given');
      out[R.question] = rows.join('; ').slice(0, 500);
    }
    return out;
  }

  // ── Step change ──
  function step(n) {
    $('step1').hidden = n !== 1; $('step2').hidden = n !== 2;
    $('mobileStickyBar').hidden = n !== 1;
    showError($('err'), '');
    if (n === 2) $('name').focus(); else $('bookingCta').focus();
  }
  $('bookingCta').onclick = function () {
    if (!state.slot) return;
    // Chip questions (e.g. riding experience) are needed before step 2.
    var missing = null;
    [].forEach.call($('groups').children, function (box, i) {
      var key = box.dataset.q; if (!key) return;
      var sq = screening().filter(function (s) { return s.key === key; })[0];
      var msg = state.answers[key] ? '' : 'Choose your ' + sq.label.toLowerCase();
      groupError(i, msg); if (msg && !missing) missing = box;
    });
    if (missing) { missing.querySelector('button').focus(); return; }
    track('book_click');
    renderStep2();
    step(2);
  };
  $('change').onclick = function () { step(1); };

  function idem(body) {
    var f = JSON.stringify([body.experience, body.starts_at, body.party_size, body.units, body.customer, body.screening_answers]);
    if (f !== state.idemFor) { state.idemFor = f; state.idemKey = rid(); }
    return state.idemKey;
  }
  var sending = false;
  $('step2').addEventListener('submit', function (e) {
    e.preventDefault();
    if (sending) return;
    var first = checkFields();
    if (first) { $(first).focus(); return; }
    var qt = quote();
    var body = { business: SLUG, experience: state.key, starts_at: state.slot.starts_at,
      customer: { name: $('name').value.trim(), email: $('email').value.trim(), phone: $('phone').value.trim() },
      screening_answers: composed(), attribution: { landing_path: location.pathname, utm_source: q.get('utm_source') || null } };
    if (qt.units) body.units = qt.units; else body.party_size = state.people;
    Object.keys(state.answers).forEach(function (k) { body.screening_answers[k] = state.answers[k]; });
    (state.questions || []).forEach(function (x, i) { body.screening_answers[x.key] = answer(i); });
    body.idempotency_key = idem(body);
    sending = true; $('requestBtn').textContent = 'Taking you to payment...';
    showError($('err'), '');
    api('POST', '/requests', body).then(function (r) {
      if (r.body.checkout_url) {
        track('checkout_start');
        // For the screen after Stripe: what was booked, and its Good to know.
        try {
          var s = state.slot;
          sessionStorage.setItem('th_bk_' + r.body.booking.ref, JSON.stringify({ key: state.key, title: labelFor(state.key),
            when: range(s.date_local, s.end_date_local) + ', ' + clock(s.time_local), party: party(state.people), lines: qt.lines, total: money(qt.total) }));
        } catch (e2) {}
        location.href = r.body.checkout_url; return;
      }
      sending = false; $('requestBtn').textContent = 'Continue to payment';
      if (r.status === 409) { state.slot = null; step(1); loadDates(); }
      showError($('err'), r.body.message || 'Something went wrong. Please try again.');
    }).catch(function () { sending = false; $('requestBtn').textContent = 'Continue to payment'; showError($('err'), 'The booking service is not reachable right now.'); });
  });

  // ── After Stripe, and the business's side ──
  function done(label, title, msg) {
    $('bpForm').hidden = true; $('bpDone').hidden = false; $('mobileStickyBar').hidden = true;
    $('doneLabel').textContent = label; $('doneTitle').textContent = title; $('doneText').textContent = msg;
    $('doneBack').href = '?x=' + state.key;
  }
  var result = q.get('result'), ref = q.get('ref');
  if (result === 'requested' && ref) {
    done('Reference ' + ref, 'Request sent', 'Your card is held, not charged. ' + BIZ + ' will confirm within 24 hours, and we\'ll email you either way. If they can\'t take you, the hold is released and you won\'t be charged.');
    booked(ref);
    var once = 'th_done_' + ref, fresh = true;
    try { fresh = !sessionStorage.getItem(once); sessionStorage.setItem(once, '1'); } catch (e) {}
    if (fresh) track('booking_completed');
    var box = $('demoBox');
    box.hidden = false;
    box.innerHTML = '<p></p><a class="btn-ghost" href="#"></a>';
    text(box.querySelector('p'), 'Demo: in the real thing, ' + BIZ + ' gets this request by text and email. Try their side now.');
    var a = box.querySelector('a'); text(a, 'See what ' + BIZ + ' sees');
    a.onclick = function (ev) {
      ev.preventDefault();
      api('GET', '/demo/links?ref=' + encodeURIComponent(ref)).then(function (r) {
        if (r.status === 200) location.href = '?x=' + state.key + '&respond=' + encodeURIComponent(r.body.respond_token);
        else { text(box.querySelector('p'), 'That demo link has expired. Make a new test booking to try again.'); a.remove(); }
      });
    };
  } else if (result === 'cancelled') {
    done('Not booked yet', 'Payment not finished', 'You left the payment page before finishing, so nothing was charged. Your places are held for a few more minutes if you want to try again.');
  } else if (q.get('respond')) {
    bizView(q.get('respond'));
  } else {
    track('page_view');
  }

  // Booking summary, then Good to know, on the screen after Stripe.
  function booked(ref) {
    var b = null;
    try { b = JSON.parse(sessionStorage.getItem('th_bk_' + ref) || 'null'); } catch (e) {}
    if (!b || !C.experiences[b.key] || !$('doneSummary')) return;
    state.key = b.key; $('doneBack').href = '?x=' + b.key;
    var rows = [[b.title, ''], [b.when, ''], [b.party, '']].concat(b.lines || []);
    var box = $('doneSummary');
    box.innerHTML = rows.map(function () { return '<div class="row"><span></span><span></span></div>'; }).join('') + '<div class="row"><b></b><b></b></div>';
    rows.forEach(function (r, i) { text(box.children[i].children[0], r[0]); text(box.children[i].children[1], r[1]); });
    box.children[0].children[0].style.fontWeight = '600';
    text(box.lastChild.children[0], 'Total (held, not charged)'); text(box.lastChild.children[1], b.total);
    box.hidden = false;
    $('doneKnow').hidden = !knowList($('doneKnowList'), C.experiences[b.key].good_to_know);
  }

  // Gallery header on mobile: the "1 / N" counter follows the carousel.
  (function () {
    var track = document.querySelector('.gallery-header__track'), now = document.querySelector('.gallery-header__now');
    if (!track || !now) return;
    var tick = false;
    track.addEventListener('scroll', function () {
      if (tick) return; tick = true;
      requestAnimationFrame(function () {
        tick = false;
        var w = track.clientWidth || 1;
        now.textContent = Math.min(track.children.length, Math.round(track.scrollLeft / w) + 1);
      });
    }, { passive: true });
  })();

  function bizView(token) {
    $('bpForm').hidden = true; $('bpBiz').hidden = false; $('mobileStickyBar').hidden = true;
    api('GET', '/respond?token=' + encodeURIComponent(token)).then(function (r) {
      if (r.status !== 200) { showError($('respErr'), r.body.message || 'This link has expired.'); return; }
      var b = r.body;
      var rows = [[b.experience, ''], [b.when, ''], [b.party_size + (b.party_size > 1 ? ' people' : ' person'), b.customer.name], ['Price', money(b.price_cents)]];
      if (b.customer.phone) rows.push(['Phone', b.customer.phone]);
      (b.details || []).forEach(function (d) { rows.push([d.label, d.answer === true ? 'Yes' : d.answer === false ? 'No' : String(d.answer)]); });
      list($('reqBox'), rows, '<div class="row"><span></span><span></span></div>').forEach(function (row, i) {
        text(row.children[0], rows[i][0]); text(row.children[1], rows[i][1]);
      });
      $('reqBox').children[0].children[0].style.fontWeight = '600';
      if (b.status === 'requested') {
        $('respActions').hidden = false;
        $('respNote').textContent = 'Their card is held. Accept to take the payment, or decline to release the hold. If nobody answers, it\'s released automatically.';
      } else respDone(b.status);
      document.querySelectorAll('#respActions [data-act]').forEach(function (btn) {
        btn.onclick = function () {
          $('respActions').hidden = true;
          api('POST', '/respond', { token: token, action: btn.dataset.act }).then(function (p) {
            if (p.status !== 200) { showError($('respErr'), p.body.message); $('respActions').hidden = false; return; }
            respDone(p.body.status);
          });
        };
      });
    });
  }
  function respDone(status) {
    $('respNote').textContent = status === 'confirmed' ? 'Accepted. The payment has been taken (test mode) and the customer is told.'
      : status === 'declined' ? 'Declined. The hold on their card is released and they aren\'t charged.'
      : 'This request is ' + status.replace(/_/g, ' ') + '.';
  }

  // ── Start ──
  if ($('stickyPrice').textContent.trim()) $('stickyPrice').dataset.fixed = $('stickyPrice').textContent.trim();
  renderChoices();
  staticContent();
  loadDates();
})();
